#requires -Version 7.1
<#
.SYNOPSIS
Generates a bounded diagnostics addon in a new directory, using an explicit existing client profile.
.NOTES
Author Malikor; no client installation or game execution. Slash commands Status, Sample, Disable. SavedVariables are schema1 bounded diagnostics; missing APIs are Unavailable, never synthetic zero CPU usage. In-game/taint validation remains NotPerformed. Destination must be new and outside any Interface/AddOns tree.
#>
[CmdletBinding()]
param([Parameter(Mandatory)][string]$Destination,[Parameter(Mandatory)][ValidatePattern('^[A-Za-z][A-Za-z0-9_]{0,47}$')][string]$Name,[Parameter(Mandatory)][string]$ProfilePath,[switch]$Json)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'lib/QualityGames.ps1');$r=QG-Result 'New-WowDiagnosticsAddon' @{profile=$ProfilePath;inGame='NotPerformed'};$code=125;$dest=$null
try{
 $new=QG-Path $Destination -New;if($new.Replace('\','/') -imatch '/Interface/AddOns(?:/|$)'){throw 'Generate outside actual client Interface/AddOns trees.'};$p=QG-Read $ProfilePath;foreach($key in @('schemaVersion','id','interfaceVersion','luaVersion','apiSources','savedVariablesFixtures','capturedUtc','verification')){if($key -cnotin @($p.Keys)){throw "Client profile missing exact property: $key"}};QG-Schema $p;QG-Int $p.interfaceVersion 1 9999999;if($p.luaVersion -isnot [string] -or $p.luaVersion -cne '5.1'){throw 'This generator targets explicitly selected Lua 5.1 profiles.'}
 $verified=& (Join-Path $PSScriptRoot 'Manage-WowClientProfile.ps1') -ProfilePath $ProfilePath;if(-not $verified.valid){throw "Client profile verification failed: $($verified.error)"}
 $template=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'lib/QualityGamesAddon.lua'));$lua=$template.Replace('__NAME__',$Name).Replace('__INTERFACE__',[string]$p.interfaceVersion).Replace('__PROFILE__',([string]$p.id -replace '[^A-Za-z0-9_-]','_'));$toc="## Interface: $($p.interfaceVersion)`n## Title: $Name Diagnostics`n## Author: Malikor`n## Version: 1.0.0`n## SavedVariables: ${Name}Diagnostics`n$Name.lua`n"
 $null=[IO.Directory]::CreateDirectory($new);$dest=$new;[IO.File]::WriteAllText((Join-Path $dest "$Name.lua"),$lua);[IO.File]::WriteAllText((Join-Path $dest "$Name.toc"),$toc)
 [IO.File]::WriteAllText((Join-Path $dest 'Mockup.svg'),'<svg xmlns="http://www.w3.org/2000/svg" width="460" height="140" viewBox="0 0 460 140"><rect width="460" height="140" fill="#16202c"/><g fill="#ffffff" font-family="sans-serif" font-size="17"><text x="20" y="34">Diagnostics Commands</text><text x="20" y="68">Status | Sample | Disable</text><text x="20" y="104">No In-Game Panel Generated</text></g></svg>')
 [IO.File]::WriteAllText((Join-Path $dest 'Diagnostics.md'),"# $Name Diagnostics`n`nGenerated for explicit profile $($p.id), Interface $($p.interfaceVersion), Lua 5.1. Author Malikor. No game/client execution or installation performed. Commands: /$($Name.ToLowerInvariant()) status, sample, disable. Disable restores the previous error handler only if this addon still owns the active handler. Other addons' later handlers are preserved.`n`nSavedVariables ${Name}Diagnostics: schemaVersion1; client/interface/source/timestamps; counters; events<=64, errors<=32, timings<=64; strings<=512. Samples are session-local and overwrite older saved diagnostics at load. CPU profiling reports Unavailable unless scriptProfile is already enabled and supported APIs return valid numbers; this addon never enables profiling. Only event names and bounded error text are stored; review SavedVariables before sharing. Import as data through Manage-WowClientProfile; never execute imported Lua.`n`nMockup.svg documents slash-command labels only. In-game compatibility, taint and performance remain NotPerformed.`n")
 foreach($f in Get-ChildItem -LiteralPath $dest -File){$r.artifacts+=QG-Artifact $f.FullName};QG-Finding $r 'generation' 'Pass' @{interface=$p.interfaceVersion;profileSource=$p.id;author='Malikor'};$code=0;$r.limitations=@('Generation only. Run Test-WowAddon and Test-WowLua with the selected profile.','Mock tests do not certify real WoW API, taint or in-game behavior.','No actual client addon folder is written. Error text may contain private information.')
}catch{$r.error=$_.Exception.Message};QG-Finish $r $code -Json:$Json -Destination $dest
